from rclpy.node import Node
from rclpy.parameter import Parameter
from rcl_interfaces.msg import SetParametersResult


class Goal(Node):
    def __init__(self):
        super().__init__('go_to_goal')
        self.declare_parameter('goal_x', 8.0)
        self.add_on_set_parameters_callback(self.check)

    def check(self, params):
        for p in params:
            if p.name == 'goal_x' and not 0.5 <= p.value <= 10.5:
                return SetParametersResult(successful=False, reason='goal outside the map')
        return SetParametersResult(successful=True)


rclpy.init()
node = Goal()
for v in (12.0, 3.0):
    r = node.set_parameters([Parameter('goal_x', value=v)])[0]
    print(v, r.successful, r.reason)
print('goal_x is', node.get_parameter('goal_x').value)
rclpy.try_shutdown()

