#include <rclcpp/rclcpp.hpp>
#include <visualization_msgs/msg/marker_array.hpp>
#include <geometry_msgs/msg/point.hpp>
using visualization_msgs::msg::Marker;

class ChikuMarkers : public rclcpp::Node {
public:
  ChikuMarkers() : Node("chiku_markers") {
    pub_ = create_publisher<visualization_msgs::msg::MarkerArray>("chiku_markers", 10);
    timer_ = create_wall_timer(std::chrono::milliseconds(500), [this]() {
      visualization_msgs::msg::MarkerArray arr;
      Marker path;
      path.header.frame_id = "map";
      path.header.stamp = now();
      path.ns = "path"; path.id = 0;
      path.type = Marker::LINE_STRIP; path.action = Marker::ADD;
      path.pose.orientation.w = 1.0;
      path.scale.x = 0.03;
      path.color.g = 1.0; path.color.a = 1.0;
      for (auto [x, y] : std::vector<std::pair<double, double>>{{0, 0}, {1, 0}, {1.5, 1}, {2.5, 1.2}}) {
        geometry_msgs::msg::Point p; p.x = x; p.y = y; path.points.push_back(p);
      }
      arr.markers.push_back(path);
      pub_->publish(arr);
    });
  }
private:
  rclcpp::Publisher<visualization_msgs::msg::MarkerArray>::SharedPtr pub_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char ** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ChikuMarkers>());
  rclcpp::shutdown();
}
